+func querySQLiteJSON(path string, query string) ([]byte, error) {
+	db, err := openSQLiteDB(path)
+	if err != nil {
+		return nil, err
+	}
+	defer func() {
+		_ = db.Close()
+	}()
+
+	rows, err := db.Query(query)
+	if err != nil {
+		return nil, err
+	}
+	defer func() {
+		_ = rows.Close()
+	}()
+
+	columns, err := rows.Columns()
+	if err != nil {
+		return nil, err
+	}
+
+	var result []map[string]string
+	for rows.Next() {
+		scanTargets := make([]sql.NullString, len(columns))
+		dest := make([]any, len(columns))
+		for i := range scanTargets {
+			dest[i] = &scanTargets[i]
+		}
+		if err := rows.Scan(dest...); err != nil {
+			return nil, err
+		}
+
+		row := make(map[string]string, len(columns))
+		for i, col := range columns {
+			if scanTargets[i].Valid {
+				row[col] = scanTargets[i].String
+			} else {
+				row[col] = ""
+			}
+		}
+		result = append(result, row)
+	}
+	if err := rows.Err(); err != nil {
+		return nil, err
+	}
+
+	if len(result) == 0 {
+		return []byte("[]"), nil
+	}
+	return json.Marshal(result)
+}
+
+func querySQLiteRaw(path string, query string) ([]byte, error) {
+	db, err := openSQLiteDB(path)
+	if err != nil {
+		return nil, err
+	}
+	defer func() {
+		_ = db.Close()
+	}()
+
+	var value sql.NullString
+	err = db.QueryRow(query).Scan(&value)
+	if errors.Is(err, sql.ErrNoRows) {
+		return []byte{}, nil
+	}
+	if err != nil {
+		return nil, err
+	}
+	if !value.Valid {
+		return []byte{}, nil
+	}
+	return []byte(value.String), nil
 }

