42	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
43		var raw hookInputRaw
44		if len(input) > 0 {
45			if err := json.Unmarshal(input, &raw); err != nil {
46				return nil, err
47			}
48		}
49	
50		switch hookName {
51		case HookNameAgentSpawn:
52			sessionID := a.generateAndCacheSessionID()
53			return &protocol.EventJSON{
54				Type:      1,
55				SessionID: sessionID,
56				Timestamp: time.Now().UTC().Format(time.RFC3339),
57			}, nil
58		case HookNameUserPromptSubmit:
59			cwd := raw.CWD
60			if cwd == "" {
61				cwd = protocol.RepoRoot()
62			}
63			sessionID, _ := a.resolveHookSessionIdentity(cwd, raw)
64			if sessionID == "" {
65				sessionID = a.generateAndCacheSessionID()
66			} else {
67				a.cacheSessionID(sessionID)
68			}
69			prompt := raw.Prompt
70			if prompt == "" {
71				prompt = os.Getenv("USER_PROMPT")
72			}
73			return &protocol.EventJSON{
74				Type:      2,
75				SessionID: sessionID,
76				Prompt:    prompt,
77				Timestamp: time.Now().UTC().Format(time.RFC3339),
78			}, nil
79		case HookNamePreToolUse:
80			return nil, nil
81		case HookNamePostToolUse:
82			if raw.ToolName != "" {
83				a.appendToolCall(raw.ToolName, raw.ToolInput)
84			}
85			return nil, nil
86		case HookNameStop:
87			cwd := raw.CWD
88			if cwd == "" {
89				cwd = protocol.RepoRoot()
90			}
91			sessionID, conversationID := a.resolveHookSessionIdentity(cwd, raw)
92			if sessionID == "" {
93				sessionID = fallbackStopSessionID()
94			}
95			a.cacheSessionID(sessionID)
96			sessionRef := a.captureTranscriptForStop(cwd, sessionID, conversationID)
97			a.clearToolCalls()
98			return &protocol.EventJSON{
99				Type:       3,
100				SessionID:  sessionID,
101				SessionRef: sessionRef,
102				Timestamp:  time.Now().UTC().Format(time.RFC3339),
103			}, nil
104		default:
105			return nil, nil
106		}
