370	// shellWrappedCommand wraps a hook command in "sh -c" with a /dev/null stdin
371	// redirect. IDEs typically run hook commands directly without a shell, so a
372	// bare "</dev/null" suffix is passed as a literal argument instead of being
373	// interpreted as a redirect. Wrapping in sh ensures the redirect works.
374	// The command content is built from compile-time constants (not user input).
375	func shellWrappedCommand(cmd string) string {
376		if runtimeGOOS == "windows" {
377			return cmd
378		}
379		return "sh -c '" + cmd + " </dev/null'"
380	}
