555	func (a *Agent) resolveHookSessionIdentity(cwd string, raw hookInputRaw) (string, string) {
556		if sessionID := rawSessionID(raw); sessionID != "" {
557			return sessionID, rawConversationID(raw)
558		}
559	
560		ideSessionID := ""
561		if cwd != "" {
562			if sessionID, err := latestIDESessionID(cwd); err == nil {
563				ideSessionID = sessionID
564			}
565		}
566	
567		conversationID := ""
568		if cwd != "" {
569			if sessionID, err := a.querySessionID(cwd); err == nil {
570				conversationID = sessionID
571			}
572		}
573	
574		if ideSessionID != "" {
575			return ideSessionID, conversationID
576		}
577		if cached := a.readCachedSessionID(); cached != "" {
578			return cached, conversationID
579		}
580		if conversationID != "" {
581			return conversationID, conversationID
582		}
583		return "", ""
584	}
