20	var runSQLiteCommand = func(args ...string) ([]byte, error) {
21		switch len(args) {
22		case 3:
23			if args[0] != "-json" {
24				return nil, fmt.Errorf("unsupported sqlite query mode: %q", args[0])
25			}
26			return querySQLiteJSON(args[1], args[2])
27		case 2:
28			return querySQLiteRaw(args[0], args[1])
29		default:
30			return nil, fmt.Errorf("unsupported sqlite invocation with %d args", len(args))
31		}
32	}
