38	func openSQLiteDB(path string) (*sql.DB, error) {
39		db, err := sql.Open("sqlite", path)
40		if err != nil {
41			return nil, err
42		}
43		return db, nil
44	}
45	
46	func querySQLiteJSON(path string, query string) ([]byte, error) {
47		db, err := openSQLiteDB(path)
48		if err != nil {
49			return nil, err
50		}
51		defer func() {
52			_ = db.Close()
53		}()
54	
55		rows, err := db.Query(query)
56		if err != nil {
57			return nil, err
58		}
59		defer func() {
60			_ = rows.Close()
61		}()
62	
63		columns, err := rows.Columns()
64		if err != nil {
65			return nil, err
66		}
67	
68		var result []map[string]string
69		for rows.Next() {
70			scanTargets := make([]sql.NullString, len(columns))
71			dest := make([]any, len(columns))
72			for i := range scanTargets {
73				dest[i] = &scanTargets[i]
74			}
75			if err := rows.Scan(dest...); err != nil {
76				return nil, err
77			}
78	
79			row := make(map[string]string, len(columns))
80			for i, col := range columns {
81				if scanTargets[i].Valid {
82					row[col] = scanTargets[i].String
83				} else {
84					row[col] = ""
85				}
86			}
87			result = append(result, row)
88		}
89		if err := rows.Err(); err != nil {
90			return nil, err
91		}
92	
93		if len(result) == 0 {
94			return []byte("[]"), nil
95		}
96		return json.Marshal(result)
97	}
98	
99	func querySQLiteRaw(path string, query string) ([]byte, error) {
100		db, err := openSQLiteDB(path)
101		if err != nil {
102			return nil, err
103		}
104		defer func() {
105			_ = db.Close()
106		}()
107	
108		var value sql.NullString
109		err = db.QueryRow(query).Scan(&value)
110		if errors.Is(err, sql.ErrNoRows) {
111			return []byte{}, nil
112		}
113		if err != nil {
114			return nil, err
115		}
116		if !value.Valid {
117			return []byte{}, nil
118		}
119		return []byte(value.String), nil
120	}
