149	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
150		if maxSize <= 0 {
151			return nil, errors.New("max-size must be greater than zero")
152		}
153		if len(content) == 0 {
154			return [][]byte{[]byte{}}, nil
155		}
156	
157		var chunks [][]byte
158		for start := 0; start < len(content); start += maxSize {
159			end := start + maxSize
160			if end > len(content) {
161				end = len(content)
162			}
163			chunk := make([]byte, end-start)
164			copy(chunk, content[start:end])
165			chunks = append(chunks, chunk)
166		}
167		return chunks, nil
168	}
