220		var query string
221		if conversationID != "" {
222			query = fmt.Sprintf(
223				"SELECT value FROM conversations_v2 WHERE json_extract(value, '$.conversation_id') = '%s' ORDER BY updated_at DESC LIMIT 1",
224				escapeSQLString(conversationID),
225			)
