227			query = fmt.Sprintf(
228				"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
229				escapeSQLString(cwd),
230			)
231		}
232	
233		out, err := runSQLiteCommand(db, query)
234		if err != nil {
235			return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
236		}
237	
238		raw := strings.TrimSpace(string(out))
239		if raw == "" {
240			return "", errors.New("no transcript found")
241		}
242	
243		cachePath, err := a.cacheTranscriptPath(cwd, sessionID)
