254		// If the transcript has no history (e.g., offset trimmed everything),
255		// return error so captureTranscriptForStop can try other sources (IDE).
256		if parsed, parseErr := parseTranscript(data); parseErr == nil && len(parsed.History) == 0 {
257			return "", errors.New("CLI transcript has no history entries")
258		}
