298	// trimTranscriptHistory trims already-checkpointed entries from a cumulative
299	// kiro transcript using a stored offset. Returns the re-serialized trimmed
300	// JSON and true if trimming was applied, or (nil, false) if the full
301	// transcript should be used as-is.
302	func (a *Agent) trimTranscriptHistory(raw []byte) ([]byte, bool) {
303		parsed, err := parseTranscript(raw)
304		if err != nil || len(parsed.History) == 0 {
305			return nil, false
306		}
307	
308		offsetPath := a.transcriptOffsetPath()
309		prev := readTranscriptOffset(offsetPath)
310		totalLen := len(parsed.History)
311	
312		trimFrom := 0
313		if prev.ConversationID == parsed.ConversationID && prev.Position > 0 && prev.Position <= totalLen {
314			trimFrom = prev.Position
315		}
316	
317		// Only update offset when there are new entries to capture.
318		if trimFrom < totalLen {
319			_ = writeTranscriptOffset(offsetPath, transcriptOffset{
320				ConversationID: parsed.ConversationID,
321				Position:       totalLen,
322			})
323		}
324	
325		if trimFrom == 0 || trimFrom >= totalLen {
326			// No trimming needed (first capture) or no new entries since last
327			// capture. Return full transcript so the caller always has content —
328			// an empty transcript would cause the CLI finalize step to fail.
329			return nil, false
330		}
331	
332		parsed.History = parsed.History[trimFrom:]
333		filtered, err := json.Marshal(parsed)
334		if err != nil {
335			return nil, false
336		}
337		return filtered, true
338	}
