340	func (a *Agent) ensureIDETranscript(cwd string, sessionID string) (string, error) {
341		sessionsDir, err := ideWorkspaceSessionsDir(cwd)
342		if err != nil {
343			return "", err
344		}
345		ideSessionID, err := latestIDESessionID(cwd)
346		if err != nil {
347			return "", err
348		}
349		if !filepath.IsLocal(ideSessionID + ".json") {
350			return "", fmt.Errorf("invalid session ID: %q", ideSessionID)
351		}
352	
353		transcriptPath := filepath.Join(sessionsDir, ideSessionID+".json")
354		transcriptData, err := os.ReadFile(transcriptPath)
355		if err != nil {
356			return "", fmt.Errorf("failed to read IDE transcript %s: %w", transcriptPath, err)
357		}
358	
359		// Enrich the IDE transcript with actual agent responses and tool calls.
360		// The IDE session format only stores "On it." as assistant content.
361		//
362		// Priority 1: Read Kiro IDE execution logs — these contain the full
363		// action trace (tool calls, responses, file modifications).
364		// Priority 2: Merge tool calls from post-tool-use hook JSONL file.
365		data := transcriptData
366		enriched := false
367		if chatSessionID := extractIDESessionID(transcriptData); chatSessionID != "" {
368			if execLogs, err := findExecutionLogsForSession(chatSessionID); err == nil && len(execLogs) > 0 {
369				if result := enrichIDETranscriptWithExecutionLogs(transcriptData, execLogs); result != nil {
370					data = result
371					enriched = true
372				}
373			}
374		}
375		if !enriched {
376			if toolCalls := a.readAndClearToolCalls(); len(toolCalls) > 0 {
377				if result := enrichIDETranscriptWithToolCalls(transcriptData, toolCalls); result != nil {
378					data = result
379				}
380			}
381		}
382	
383		// Trim already-checkpointed entries from cumulative IDE transcript.
384		if filtered, ok := a.trimTranscriptHistory(data); ok {
385			data = filtered
386		}
387		data = injectTranscriptCLIVersion(data, currentCLIVersion())
388	
389		if parsed, parseErr := parseTranscript(data); parseErr == nil && len(parsed.History) == 0 {
390			return "", errors.New("IDE transcript has no history entries after trimming")
391		}
392	
393		cachePath, err := a.cacheTranscriptPath(cwd, sessionID)
394		if err != nil {
395			return "", err
396		}
397		if err := os.WriteFile(cachePath, data, 0o600); err != nil {
398			return "", fmt.Errorf("failed to write cached IDE transcript: %w", err)
399		}
400		return cachePath, nil
401	}
402	
403	// enrichIDETranscriptWithToolCalls converts an IDE transcript to CLI format
404	// and injects the captured tool calls into the last assistant entry. Returns
405	// the re-serialized CLI-format JSON, or nil if conversion fails.
406	func enrichIDETranscriptWithToolCalls(ideData []byte, toolCalls []kiroToolCall) []byte {
407		converted := tryParseIDETranscript(ideData)
408		if converted == nil || len(converted.History) == 0 {
409			return nil
410		}
411	
412		// Assign all tool calls to the last assistant entry, since post-tool-use
413		// hooks fire between user-prompt-submit and stop for the current turn.
414		toolUse := kiroToolUseContent{
415			ToolUse: kiroToolUsePayload{ToolUses: toolCalls},
416		}
417		toolUseJSON, err := json.Marshal(toolUse)
418		if err != nil {
419			return nil
420		}
421	
422		lastIdx := len(converted.History) - 1
423		converted.History[lastIdx].Assistant = toolUseJSON
424	
425		result, err := json.Marshal(converted)
426		if err != nil {
427			return nil
428		}
429		return result
430	}
