668	func convertIDETranscript(ide *kiroIDETranscript) *kiroTranscript {
669		transcript := &kiroTranscript{CLIVersion: ide.CLIVersion}
670	
671		var pendingUser *kiroIDEHistoryEntry
672		for i := range ide.History {
673			entry := &ide.History[i]
674			switch entry.Message.Role {
675			case "user":
676				if pendingUser != nil {
677					transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
678				}
679				pendingUser = entry
680			case "assistant":
681				transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, entry))
682				pendingUser = nil
683			}
684		}
685	
686		if pendingUser != nil {
687			transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
688		}
689	
690		return transcript
691	}
