730	func ideEntryToPaired(user, assistant *kiroIDEHistoryEntry) kiroHistoryEntry {
731		entry := kiroHistoryEntry{}
732	
733		if user != nil {
734			prompt := extractIDEText(user.Message.Content, true)
735			if prompt != "" {
736				content, err := json.Marshal(kiroPromptContent{
737					Prompt: struct {
738						Prompt string `json:"prompt"`
739					}{Prompt: prompt},
740				})
741				if err == nil {
742					entry.User.Content = content
743				}
744			} else {
745				entry.User.Content = user.Message.Content
746			}
747		}
748	
749		if assistant != nil {
750			text := extractIDEText(assistant.Message.Content, false)
751			if text != "" {
752				content, err := json.Marshal(kiroResponseContent{
753					Response: kiroResponsePayload{Content: text},
754				})
755				if err == nil {
756					entry.Assistant = content
757				}
758			} else {
759				entry.Assistant = assistant.Message.Content
760			}
761		}
