766	// extractIDEText extracts text from a json.RawMessage that may be either a
767	// plain string or an array of content blocks. When blocksFirst is true, it
768	// tries to parse as blocks before falling back to a plain string (user
769	// messages); otherwise it tries plain string first (assistant messages).
770	func extractIDEText(content json.RawMessage, blocksFirst bool) string {
771		if len(content) == 0 {
772			return ""
773		}
774	
775		tryBlocks := func() string {
776			var blocks []kiroIDEContentBlock
777			if err := json.Unmarshal(content, &blocks); err == nil && len(blocks) > 0 {
778				for _, block := range blocks {
779					if block.Type == "text" && block.Text != "" {
780						return block.Text
781					}
782				}
783			}
784			return ""
785		}
786	
787		tryString := func() string {
788			var text string
789			if err := json.Unmarshal(content, &text); err == nil {
790				return text
791			}
792			return ""
793		}
794	
795		if blocksFirst {
796			if s := tryBlocks(); s != "" {
797				return s
798			}
799			return tryString()
800		}
801		if s := tryString(); s != "" {
802			return s
803		}
804		return tryBlocks()
805	}
