927	// findExecutionLogsForSession scans Kiro IDE workspace directories to find
928	// execution log files matching the given chat session ID. Returns a map of
929	// executionId → *kiroExecutionLog.
930	func findExecutionLogsForSession(chatSessionID string) (map[string]*kiroExecutionLog, error) {
931		baseDir, err := kiroExtensionStorageDir()
932		if err != nil {
933			return nil, err
934		}
935	
936		entries, err := os.ReadDir(baseDir)
937		if err != nil {
938			return nil, err
939		}
940	
941		for _, entry := range entries {
942			if !entry.IsDir() || len(entry.Name()) != 32 {
943				continue
944			}
945			logsDir := filepath.Join(baseDir, entry.Name(), execLogsSubdir)
946			if _, err := os.Stat(logsDir); err != nil {
947				continue
948			}
949			logs := scanExecutionLogsDir(logsDir, chatSessionID)
950			if len(logs) > 0 {
951				return logs, nil
952			}
953		}
954	
955		return map[string]*kiroExecutionLog{}, nil
956	}
