958	// scanExecutionLogsDir reads all execution log files in a directory and returns
959	// those matching the given chat session ID.
960	func scanExecutionLogsDir(dir string, chatSessionID string) map[string]*kiroExecutionLog {
961		files, err := os.ReadDir(dir)
962		if err != nil {
963			return nil
964		}
965	
966		// Two-pass approach: first identify matching files using a lightweight
967		// struct (avoids deserializing the large Actions array), then fully
968		// parse only the matches.
969		var matchingPaths []string
970		for _, f := range files {
971			if f.IsDir() {
972				continue
973			}
974			path := filepath.Join(dir, f.Name())
975			data, err := os.ReadFile(path)
976			if err != nil {
977				continue
978			}
979			var header struct {
980				ChatSessionID string `json:"chatSessionId"`
981			}
982			if json.Unmarshal(data, &header) == nil && header.ChatSessionID == chatSessionID {
983				matchingPaths = append(matchingPaths, path)
984			}
985		}
986	
987		if len(matchingPaths) == 0 {
988			return nil
989		}
990	
991		result := make(map[string]*kiroExecutionLog, len(matchingPaths))
992		for _, path := range matchingPaths {
993			data, err := os.ReadFile(path)
994			if err != nil {
995				continue
996			}
997			var log kiroExecutionLog
998			if err := json.Unmarshal(data, &log); err != nil {
999				continue
1000			}
1001			result[log.ExecutionID] = &log
1002		}
1003		return result
1004	}
