1006	// convertExecutionActionsToHistoryEntries converts Kiro IDE execution log
1007	// actions into CLI transcript history entries. Tool-modifying actions (create,
1008	// edit) become ToolUse entries; say actions become Response entries.
1009	func convertExecutionActionsToHistoryEntries(actions []kiroExecutionAction) []kiroHistoryEntry {
1010		var toolCalls []kiroToolCall
1011		var entries []kiroHistoryEntry
1012	
1013		for _, action := range actions {
1014			if toolName, ok := execActionToToolName[action.ActionType]; ok {
1015				filePath := extractFilePath(action.Input)
1016				if filePath != "" {
1017					args, err := json.Marshal(map[string]string{"path": filePath})
1018					if err != nil {
1019						continue
1020					}
1021					toolCalls = append(toolCalls, kiroToolCall{
1022						Name: toolName,
1023						Args: args,
1024					})
1025				}
1026			}
1027			if action.ActionType == "say" {
1028				var out struct {
1029					Message string `json:"message"`
1030				}
1031				if err := json.Unmarshal(action.Output, &out); err == nil && out.Message != "" {
1032					// Flush any pending tool calls first
1033					if len(toolCalls) > 0 {
1034						toolUseJSON, err := json.Marshal(kiroToolUseContent{
1035							ToolUse: kiroToolUsePayload{ToolUses: toolCalls},
1036						})
1037						if err == nil {
1038							entries = append(entries, kiroHistoryEntry{Assistant: toolUseJSON})
1039						}
1040						toolCalls = nil
1041					}
1042					responseJSON, err := json.Marshal(kiroResponseContent{
1043						Response: kiroResponsePayload{Content: out.Message},
1044					})
1045					if err == nil {
1046						entries = append(entries, kiroHistoryEntry{Assistant: responseJSON})
1047					}
1048				}
1049			}
1050		}
1051	
1052		// Flush remaining tool calls without a trailing say
1053		if len(toolCalls) > 0 {
1054			toolUseJSON, err := json.Marshal(kiroToolUseContent{
1055				ToolUse: kiroToolUsePayload{ToolUses: toolCalls},
1056			})
1057			if err == nil {
1058				entries = append(entries, kiroHistoryEntry{Assistant: toolUseJSON})
1059			}
1060		}
1061	
1062		return entries
1063	}
1064	
1065	// enrichIDETranscriptWithExecutionLogs converts an IDE transcript to CLI
1066	// format and replaces "On it." assistant entries with actual data from
1067	// execution logs. Returns the re-serialized CLI-format JSON, or nil if
1068	// conversion fails.
1069	func enrichIDETranscriptWithExecutionLogs(ideData []byte, execLogs map[string]*kiroExecutionLog) []byte {
1070		var meta kiroIDESessionMeta
1071		if err := json.Unmarshal(ideData, &meta); err != nil {
1072			return nil
1073		}
1074		if len(meta.History) == 0 {
1075			return nil
1076		}
1077	
1078		// Convert to CLI format, enriching assistant entries from execution logs.
1079		// kiroIDEHistoryMeta contains both the Message (for pairing) and the
1080		// ExecutionID (for matching against execution logs).
1081		transcript := &kiroTranscript{}
1082		var pendingUser *kiroIDEHistoryEntry
1083		for i := range meta.History {
1084			// Adapt meta entry to IDE entry (they share the same Message field)
1085			ideEntry := &kiroIDEHistoryEntry{Message: meta.History[i].Message}
1086			switch ideEntry.Message.Role {
1087			case "user":
1088				if pendingUser != nil {
1089					transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
1090				}
1091				pendingUser = ideEntry
1092			case "assistant":
1093				if execID := meta.History[i].ExecutionID; execID != "" {
1094					if execLog, ok := execLogs[execID]; ok {
1095						userEntry := ideEntryToPaired(pendingUser, nil)
1096						assistantEntries := convertExecutionActionsToHistoryEntries(execLog.Actions)
1097						if len(assistantEntries) > 0 {
1098							userEntry.Assistant = assistantEntries[0].Assistant
1099							transcript.History = append(transcript.History, userEntry)
1100							transcript.History = append(transcript.History, assistantEntries[1:]...)
1101							pendingUser = nil
1102							continue
1103						}
1104					}
1105				}
1106				transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, ideEntry))
1107				pendingUser = nil
1108			}
1109		}
1110		if pendingUser != nil {
1111			transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
1112		}
1113	
1114		result, err := json.Marshal(transcript)
1115		if err != nil {
1116			return nil
1117		}
1118		return result
1119	}
