		filepath.Join(repoRoot, ".kiro", "hooks", "entire-post-tool-use.kiro.hook"),
		filepath.Join(repoRoot, ".vscode", "settings.json"),
	} {
		data, err := os.ReadFile(p)
		if err != nil {
			t.Logf("--- %s: missing (%v)\n", p, err)
			continue
		}
		t.Logf("--- %s ---\n%s", p, data)
	}
}

func TestDumpWindowsLocalDevHookArtifacts(t *testing.T) {
	if os.Getenv("INSPECT") == "" {
