43	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
44		var raw hookInputRaw
45		if len(input) > 0 {
46			if err := json.Unmarshal(input, &raw); err != nil {
47				return nil, err
48			}
49		}
50	
51		switch hookName {
52		case HookNameAgentSpawn:
53			sessionID := a.generateAndCacheSessionID()
54			return &protocol.EventJSON{
55				Type:      1,
56				SessionID: sessionID,
57				Timestamp: time.Now().UTC().Format(time.RFC3339),
58			}, nil
59		case HookNameUserPromptSubmit:
60			cwd := raw.CWD
61			if cwd == "" {
62				cwd = protocol.RepoRoot()
63			}
64			sessionID, _ := a.resolveHookSessionIdentity(cwd, raw)
65			if sessionID == "" {
66				sessionID = a.generateAndCacheSessionID()
67			} else {
68				a.cacheSessionID(sessionID)
69			}
70			prompt := raw.Prompt
71			if prompt == "" {
72				prompt = os.Getenv("USER_PROMPT")
73			}
74			return &protocol.EventJSON{
75				Type:      2,
76				SessionID: sessionID,
77				Prompt:    prompt,
78				Timestamp: time.Now().UTC().Format(time.RFC3339),
79			}, nil
80		case HookNamePreToolUse:
81			return nil, nil
82		case HookNamePostToolUse:
83			if raw.ToolName != "" {
84				a.appendToolCall(raw.ToolName, raw.ToolInput)
85			}
86			return nil, nil
87		case HookNameStop:
88			cwd := raw.CWD
89			if cwd == "" {
90				cwd = protocol.RepoRoot()
91			}
92			sessionID, conversationID := a.resolveHookSessionIdentity(cwd, raw)
93			if sessionID == "" {
94				sessionID = fallbackStopSessionID()
95			}
96			a.cacheSessionID(sessionID)
97			sessionRef := a.captureTranscriptForStop(cwd, sessionID, conversationID)
98			a.clearToolCalls()
99			return &protocol.EventJSON{
100				Type:       3,
101				SessionID:  sessionID,
102				SessionRef: sessionRef,
103				Timestamp:  time.Now().UTC().Format(time.RFC3339),
104			}, nil
105		default:
106			return nil, nil
107		}
108	}
